import { useState } from "react";
import { PageTitle, Card, Btn, Input, Textarea, Ic, ICONS } from "../components/UI";

const API_BASE = process.env.REACT_APP_API_URL || "http://localhost:8001";

export default function Generators({ t, toast }) {
  const [token] = useState(localStorage.getItem("ns_token"));
  const [loading, setLoading] = useState(false);
  const [docType, setDocType] = useState("Rent Agreement");
  const [form, setForm] = useState({ party_a: "", party_b: "", details: "" });
  const [result, setResult] = useState("");

  const handleGenerate = async () => {
    if (!token) return toast("Please login via Dashboard first", "error");
    if (!form.party_a || !form.party_b || !form.details) return toast("Fill all fields", "error");

    setLoading(true);
    try {
      const res = await fetch(`${API_BASE}/api/generate_doc`, {
        method: "POST",
        headers: { "Content-Type": "application/json", "Authorization": `Bearer ${token}` },
        body: JSON.stringify({ doc_type: docType, ...form })
      });
      const data = await res.json();
      if (res.ok) {
        setResult(data.content);
        toast("Document Generated", "success");
      } else {
        toast(data.detail || "Error generating document", "error");
      }
    } catch (e) {
      toast("Server Error", "error");
    }
    setLoading(false);
  };

  const getPlaceholderA = () => {
    switch (docType) {
      case "Rent Agreement": return "Landlord Name";
      case "Legal Notice": return "Sender Name";
      case "Affidavit": return "Deponent Name";
      case "Power of Attorney": return "Principal Name";
      case "Will": return "Testator Name";
      case "Partnership Deed": return "Partner 1 Name";
      default: return "Party A";
    }
  };

  const getPlaceholderB = () => {
    switch (docType) {
      case "Rent Agreement": return "Tenant Name";
      case "Legal Notice": return "Recipient Name";
      case "Affidavit": return "N/A (Leave empty or NA)";
      case "Power of Attorney": return "Attorney Name";
      case "Will": return "Executor Name";
      case "Partnership Deed": return "Partner 2 Name";
      default: return "Party B";
    }
  };

  const getPlaceholderDetails = () => {
    switch (docType) {
      case "Rent Agreement": return "Property address, rent amount, tenure...";
      case "Legal Notice": return "Subject of the notice, demands...";
      case "Affidavit": return "Purpose, specific facts, circumstances...";
      case "Power of Attorney": return "Purpose, schedule of properties, duration...";
      case "Will": return "Bequests, specific directions, properties...";
      case "Partnership Deed": return "Business object, address, capital_a, capital_b...";
      default: return "Details...";
    }
  };

  return (
    <div style={{ maxWidth: 1000, margin: "40px auto", padding: "0 20px" }}>
      <PageTitle
        icon="doc"
        title="AI Legal Document Generator"
        desc="Instantly draft Rent Agreements, Legal Notices, and more using structured templates."
        badge="BETA"
        t={t}
      />

      <div style={{ display: "grid", gridTemplateColumns: "340px 1fr", gap: 24 }}>
        <Card t={t} style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <h3 style={{ margin: "0 0 8px", fontSize: 16, fontWeight: 800 }}>Document Details</h3>

          <select value={docType} onChange={e => setDocType(e.target.value)} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 9, padding: "10px 16px", color: t.text, fontFamily: "inherit" }}>
            <option value="Rent Agreement">Rent Agreement</option>
            <option value="Legal Notice">Legal Notice</option>
            <option value="Affidavit">Affidavit</option>
            <option value="Power of Attorney">Power of Attorney</option>
            <option value="Will">Will</option>
            <option value="Partnership Deed">Partnership Deed</option>
          </select>

          <Input
            value={form.party_a}
            onChange={e => setForm({ ...form, party_a: e.target.value })}
            placeholder={getPlaceholderA()}
            t={t}
          />
          <Input
            value={form.party_b}
            onChange={e => setForm({ ...form, party_b: e.target.value })}
            placeholder={getPlaceholderB()}
            t={t}
          />
          <Textarea
            value={form.details}
            onChange={e => setForm({ ...form, details: e.target.value })}
            placeholder={getPlaceholderDetails()}
            rows={6}
            t={t}
          />

          <Btn onClick={handleGenerate} loading={loading} t={t} style={{ width: "100%", justifyContent: "center", marginTop: 8 }}>
            Generate Document
          </Btn>
        </Card>

        <Card t={t}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
            <h3 style={{ margin: 0, fontSize: 16, fontWeight: 800 }}>Generated Output</h3>
            {result && <Btn outline small onClick={() => { navigator.clipboard.writeText(result); toast("Copied!", "success"); }} t={t}>Copy</Btn>}
          </div>

          <div style={{
            background: t.surfaceUp,
            border: `1.5px solid ${t.border}`,
            borderRadius: 12,
            padding: 20,
            minHeight: 400,
            whiteSpace: "pre-wrap",
            fontFamily: "monospace",
            fontSize: 13,
            lineHeight: 1.6,
            color: result ? t.text : t.sub
          }}>
            {result || "Your generated document will appear here..."}
          </div>
        </Card>
      </div>
    </div>
  );
}
